    tree = ast.parse(text, mode="eval")
    tree = ast.fix_missing_locations(ExactDivision().visit(tree))
    value = eval(
        compile(tree, "<expression>", "eval"),
        {"__builtins__": {}, "Fraction": Fraction, "max": max, "min": min},
    )
    if type(value) is not bool:
        raise ValueError("Expression did not evaluate to a Boolean")
    return value


